// ELEMENTS:
// 1. Navy liso com o filete vermelho no topo
// 2. Título (title) em Light com traço vermelho
// 3. Uma régua por item ("Rótulo: 2,3 × IAS"): marcas de 0 ao maior valor, barra branca a crescer
//    até ao valor e o valor em Light a contar (times = segundos em que cada barra entra)
// 4. Sub em névoa no fundo
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const LINE = "rgba(255,255,255,0.45)";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.08, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

// "2,3 × IAS" → 2.3 (pt-PT comma decimals)
const num = (s: string): number => {
  const m = s.match(/\d+(,\d+)?/);
  return m ? parseFloat(m[0].replace(",", ".")) : 0;
};
const fmt = (v: number, like: string): string => {
  const m = like.match(/\d+(,\d+)?/);
  if (!m) return like;
  const dec = m[1] ? m[1].length - 1 : 0;
  return like.slice(0, m.index) + v.toFixed(dec).replace(".", ",") + like.slice((m.index ?? 0) + m[0].length);
};

const BarrasComparacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const title = String(p.title ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const raw = Array.isArray(p.items) ? (p.items as unknown[]).map(String) : String(anim.text ?? "").split("|");
  const items = raw.map((s) => s.trim()).filter(Boolean).map((s) => {
    const i = s.indexOf(":");
    const value = i > 0 ? s.slice(i + 1).trim() : s;
    return { label: i > 0 ? s.slice(0, i).trim() : "", value, n: num(value) };
  });
  const max = Math.max(1, ...items.map((x) => x.n));
  const steps = max <= 12 ? Math.ceil(max) : 10;
  const times = Array.isArray(p.times) ? (p.times as unknown[]).map(Number) : [];

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const trackW = 900 * u;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ justifyContent: "center", padding: `0 ${90 * u}px`, gap: 70 * u }}>
        {title ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 26 * u, opacity: show(0.1), transform: `translateY(${(1 - show(0.1)) * 26 * u}px)` }}>
            <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 96 * u, lineHeight: 1.05, color: WHITE }}>{title}</div>
            <div style={{ width: show(0.4, 0.7) * 110 * u, height: 3 * u, background: RED }} />
          </div>
        ) : null}
        {items.map((it, i) => {
          const at = Number.isFinite(times[i]) ? times[i] : 0.6 + i * 1.2;
          const t = show(at, 0.6);
          const grow = interpolate(f, [Math.round((at + 0.3) * fps), Math.round((at + 1.8) * fps)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
          return (
            <div key={i} style={{ display: "flex", flexDirection: "column", gap: 20 * u, opacity: t, transform: `translateY(${(1 - t) * 24 * u}px)` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 30 * u }}>
                <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST }}>{it.label}</div>
                <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 72 * u, color: WHITE, whiteSpace: "nowrap", fontVariantNumeric: "lining-nums tabular-nums" }}>{fmt(it.n * grow, it.value)}</div>
              </div>
              <div style={{ position: "relative", width: trackW, height: 46 * u }}>
                <div style={{ position: "absolute", left: 0, right: 0, top: 22 * u, height: 1.5 * u, background: LINE }} />
                {Array.from({ length: steps + 1 }, (_, k) => (
                  <div key={k} style={{ position: "absolute", left: (k / steps) * trackW - 1 * u, top: 12 * u, width: 2 * u, height: 22 * u, background: "rgba(255,255,255,0.3)" }} />
                ))}
                <div style={{ position: "absolute", left: 0, top: 10 * u, height: 26 * u, width: (it.n / max) * trackW * grow, background: WHITE, borderRadius: 13 * u }} />
                <div style={{ position: "absolute", left: (it.n / max) * trackW * grow - 8 * u, top: 15 * u, width: 16 * u, height: 16 * u, borderRadius: 8 * u, background: RED, opacity: grow > 0.02 ? 1 : 0 }} />
              </div>
            </div>
          );
        })}
        {sub ? (
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 46 * u, lineHeight: 1.25, color: MIST, opacity: show((Number.isFinite(times[items.length - 1]) ? times[items.length - 1] : 0.6 + items.length * 1.2) + 1.6) }}>{sub}</div>
        ) : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default BarrasComparacao;
